using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

namespace ApiMcpServer.Tools;

/// <summary>
/// MCP tools that wrap the JSONPlaceholder REST API.
/// Constructor-injected services (IHttpClientFactory, ILogger) are resolved
/// by the MCP SDK via DI and never appear in the tool schema.
/// </summary>
[McpServerToolType]
public class ApiTools(IHttpClientFactory httpFactory, ILogger<ApiTools> logger)
{
    private static readonly JsonSerializerOptions JsonOptions = new() { WriteIndented = true };

    [McpServerTool, Description("Get a post by its numeric ID from the REST API.")]
    public async Task<string> GetPost(
        [Description("The numeric ID of the post (1-100).")] int id,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching post {Id}", id);
        var client = httpFactory.CreateClient("api");
        var post = await client.GetFromJsonAsync<JsonElement>(
            $"/posts/{id}", cancellationToken);
        return JsonSerializer.Serialize(post, JsonOptions);
    }

    [McpServerTool, Description("List all posts, optionally filtered by user ID.")]
    public async Task<string> ListPosts(
        [Description("Optional user ID to filter posts by author.")] int? userId = null,
        CancellationToken cancellationToken = default)
    {
        var client = httpFactory.CreateClient("api");
        var url = userId.HasValue ? $"/posts?userId={userId}" : "/posts";
        var posts = await client.GetFromJsonAsync<JsonElement>(url, cancellationToken);
        return JsonSerializer.Serialize(posts, JsonOptions);
    }

    [McpServerTool, Description("Get all comments for a specific post.")]
    public async Task<string> GetComments(
        [Description("The post ID to retrieve comments for.")] int postId,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching comments for post {PostId}", postId);
        var client = httpFactory.CreateClient("api");
        var comments = await client.GetFromJsonAsync<JsonElement>(
            $"/posts/{postId}/comments", cancellationToken);
        return JsonSerializer.Serialize(comments, JsonOptions);
    }

    [McpServerTool(Destructive = false, ReadOnly = true),
     Description("Search for users by name or username.")]
    public async Task<string> SearchUsers(
        [Description("Search term to match against user name or username.")] string query,
        CancellationToken cancellationToken = default)
    {
        var client = httpFactory.CreateClient("api");
        var users = await client.GetFromJsonAsync<JsonElement[]>(
            "/users", cancellationToken);

        var matches = users?
            .Where(u =>
                u.GetProperty("name").GetString()?.Contains(query, StringComparison.OrdinalIgnoreCase) == true ||
                u.GetProperty("username").GetString()?.Contains(query, StringComparison.OrdinalIgnoreCase) == true)
            .ToArray() ?? [];

        return JsonSerializer.Serialize(matches, JsonOptions);
    }
}

